"use client"

import {
  getPartText,
  INPUT_TEXT_ITEM_TYPE,
  useContext,
  type ContextEventForUI,
  type SendStatus,
  type UseContextOptions,
} from "@ekairos/events/react"
import { type FormEvent, useMemo, useState } from "react"

import "./context-chat.css"

export type ContextChatProps = UseContextOptions & {
  db: any
  className?: string
  emptyLabel?: string
  placeholder?: string
  submitLabel?: string
}

export type MessageListProps = {
  events: readonly ContextEventForUI[]
  emptyLabel?: string
}

export type PromptBarProps = {
  onSubmit(prompt: string): Promise<void> | void
  status: SendStatus
  error?: string | null
  placeholder?: string
  submitLabel?: string
}

export function ContextChat({
  db,
  className,
  emptyLabel,
  placeholder,
  submitLabel,
  ...options
}: ContextChatProps) {
  const context = useContext(db, options)

  return (
    <section className={["context-chat", className].filter(Boolean).join(" ")}>
      <header className="context-chat-header">
        <div>
          <span>Context</span>
          <strong>{context.context?.name ?? context.context?.key ?? context.contextId ?? "New context"}</strong>
        </div>
        <output data-status={context.sendStatus}>{context.sendStatus}</output>
      </header>
      <MessageList events={context.events} emptyLabel={emptyLabel} />
      <PromptBar
        error={context.sendError}
        onSubmit={prompt => context.append({ parts: [{ type: "text", text: prompt }] })}
        placeholder={placeholder}
        status={context.sendStatus}
        submitLabel={submitLabel}
      />
    </section>
  )
}

export function MessageList({
  events,
  emptyLabel = "No events yet.",
}: MessageListProps) {
  const messages = useMemo(() => events.map(event => ({
    event,
    role: event.type === INPUT_TEXT_ITEM_TYPE || event.type.startsWith("user.")
      ? "user"
      : "assistant",
    text: eventText(event),
  })), [events])

  return (
    <div className="context-chat-messages" aria-live="polite">
      {messages.length === 0 ? (
        <p className="context-chat-empty">{emptyLabel}</p>
      ) : messages.map(({ event, role, text }) => (
        <article
          className="context-chat-message"
          data-durability={event.durability ?? "durable"}
          data-role={role}
          key={event.id}
        >
          <header>
            <span>{role}</span>
            <span>{event.durability ?? "durable"}</span>
          </header>
          <p>{text || event.type}</p>
        </article>
      ))}
    </div>
  )
}

export function PromptBar({
  onSubmit,
  status,
  error,
  placeholder = "Message this context…",
  submitLabel = "Send",
}: PromptBarProps) {
  const [draft, setDraft] = useState("")
  const ready = status === "idle" && draft.trim().length > 0

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (!ready) return
    const prompt = draft.trim()
    setDraft("")
    try {
      await onSubmit(prompt)
    } catch {
      setDraft(prompt)
    }
  }

  return (
    <form className="context-chat-prompt" onSubmit={submit}>
      {error ? <p role="alert">{error}</p> : null}
      <div>
        <textarea
          aria-label={placeholder}
          disabled={status !== "idle"}
          onChange={event => setDraft(event.target.value)}
          onKeyDown={event => {
            if (event.key === "Enter" && !event.shiftKey) {
              event.preventDefault()
              event.currentTarget.form?.requestSubmit()
            }
          }}
          placeholder={placeholder}
          rows={2}
          value={draft}
        />
        <button disabled={!ready} type="submit">
          {status === "idle" ? submitLabel : status}
        </button>
      </div>
    </form>
  )
}

function eventText(event: ContextEventForUI) {
  const text = event.eventParts.map(getPartText).filter(Boolean).join("\n\n")
  if (text) return text
  if (typeof event.payload === "string") return event.payload
  if (!event.payload || typeof event.payload !== "object") return ""
  const payload = event.payload as Record<string, unknown>
  return typeof payload.text === "string"
    ? payload.text
    : typeof payload.message === "string"
      ? payload.message
      : ""
}

.context-chat {
  --context-chat-bg: var(--background, #000);
  --context-chat-panel: var(--card, #07090a);
  --context-chat-line: var(--border, rgba(255, 255, 255, 0.12));
  --context-chat-text: var(--foreground, #f4f7f8);
  --context-chat-muted: var(--muted-foreground, rgba(244, 247, 248, 0.58));
  --context-chat-accent: var(--primary, #7defff);
  --context-chat-accent-text: var(--primary-foreground, #001013);
  --context-chat-danger: var(--destructive, #ff5c67);
  --context-chat-stream: var(--event-timeline-accent, #7defff);
  --context-chat-user: rgba(125, 239, 255, 0.08);
  --context-chat-assistant: rgba(255, 255, 255, 0.025);
  --context-chat-font: var(
    --font-sans,
    Inter,
    ui-sans-serif,
    system-ui,
    sans-serif
  );
  --context-chat-mono: var(
    --font-mono,
    ui-monospace,
    SFMono-Regular,
    Menlo,
    Consolas,
    monospace
  );

  min-height: 28rem;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  overflow: hidden;
  border: 1px solid var(--context-chat-line);
  background: var(--context-chat-bg);
  color: var(--context-chat-text);
  font-family: var(--context-chat-font);
}

.context-chat *,
.context-chat *::before,
.context-chat *::after {
  box-sizing: border-box;
}

.context-chat-header {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.8rem 1rem;
  border-bottom: 1px solid var(--context-chat-line);
  background: var(--context-chat-panel);
}

.context-chat-header > div {
  min-width: 0;
  display: grid;
  gap: 0.2rem;
}

.context-chat-header span,
.context-chat-header output,
.context-chat-message header {
  color: var(--context-chat-muted);
  font: 600 0.66rem/1 var(--context-chat-mono);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.context-chat-header strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.9rem;
}

.context-chat-header output {
  margin-left: auto;
}

.context-chat-header output[data-status="streaming"] {
  color: var(--context-chat-stream);
}

.context-chat-messages {
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
  overflow-y: auto;
  padding: 1rem;
}

.context-chat-empty {
  margin: auto;
  color: var(--context-chat-muted);
  font-size: 0.82rem;
}

.context-chat-message {
  width: min(82%, 42rem);
  padding: 0.7rem 0.8rem;
  border: 1px solid var(--context-chat-line);
  background: var(--context-chat-assistant);
}

.context-chat-message[data-role="user"] {
  align-self: flex-end;
  background: var(--context-chat-user);
}

.context-chat-message[data-durability="streaming"] {
  border-color: var(--context-chat-stream);
}

.context-chat-message header {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.45rem;
}

.context-chat-message p {
  margin: 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-size: 0.86rem;
  line-height: 1.55;
}

.context-chat-prompt {
  padding: 0.75rem;
  border-top: 1px solid var(--context-chat-line);
  background: var(--context-chat-panel);
}

.context-chat-prompt > p {
  margin: 0 0 0.6rem;
  color: var(--context-chat-danger);
  font-size: 0.78rem;
}

.context-chat-prompt > div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.6rem;
  align-items: end;
}

.context-chat-prompt textarea {
  width: 100%;
  min-height: 3.2rem;
  resize: vertical;
  border: 1px solid var(--context-chat-line);
  border-radius: 0;
  outline: 0;
  padding: 0.7rem;
  background: var(--context-chat-bg);
  color: var(--context-chat-text);
  font: inherit;
}

.context-chat-prompt textarea:focus {
  border-color: var(--context-chat-accent);
}

.context-chat-prompt textarea::placeholder {
  color: var(--context-chat-muted);
}

.context-chat-prompt button {
  min-height: 2.5rem;
  border: 1px solid var(--context-chat-accent);
  border-radius: 0;
  padding: 0 1rem;
  background: var(--context-chat-accent);
  color: var(--context-chat-accent-text);
  font: 700 0.75rem/1 var(--context-chat-mono);
  cursor: pointer;
}

.context-chat-prompt button:disabled,
.context-chat-prompt textarea:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}
